190.     /// <summary>
191.     /// Creates a per-run copy.  Scalar fields are copied by value and the mutable
192.     /// collections are re-wrapped in fresh instances so mutating the clone (e.g.
193.     /// accumulating judge tokens) never affects the source.  This is essential when a
194.     /// cached baseline is reused concurrently across parallel target evaluations: each
195.     /// evaluation works on its own copy instead of sharing one mutable instance.
196.     /// </summary>
197.     public RunMetrics Clone() => new()
198.     {
199.         TokenEstimate = TokenEstimate,
200.         InputTokens = InputTokens,
201.         OutputTokens = OutputTokens,
202.         CacheReadTokens = CacheReadTokens,
203.         CacheWriteTokens = CacheWriteTokens,
204.         JudgeInputTokens = JudgeInputTokens,
205.         JudgeOutputTokens = JudgeOutputTokens,
206.         JudgeCacheReadTokens = JudgeCacheReadTokens,
207.         JudgeCacheWriteTokens = JudgeCacheWriteTokens,
208.         ToolCallCount = ToolCallCount,
209.         ToolCallBreakdown = new Dictionary<string, int>(ToolCallBreakdown),
210.         TurnCount = TurnCount,
211.         WallTimeMs = WallTimeMs,
212.         ErrorCount = ErrorCount,
213.         TimedOut = TimedOut,
214.         AssertionResults = [.. AssertionResults],
215.         TaskCompleted = TaskCompleted,
216.         AgentOutput = AgentOutput,
217.         Events = [.. Events],
218.         WorkDir = WorkDir,
219.     };
220. }
